void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
  // uvx2
  vec2 p = (fragCoord * 2.0 - iResolution.xy) / iResolution.x;

  // viewport
  p *= 10.0;
  p.y -= 2.3;

  // heart curve
  float a = atan(p.x, p.y);
  float d = .1 + 2. * abs(a) - length(p);

  // output to screen
  fragColor = vec4(d, 0.0, 0.0, 1.0);
}
